#[tokio::test]
async fn maps_brands_catalog() {
    let server = MockServer::start().await;
    mount(
        &server,
        "GET",
        "/api/v1/brands/catalog/",
        envelope_for("brands_catalog"),
    )
    .await;
    let client = client_for(&server);
    let params: BrandsCatalogParams =
        serde_json::from_str(r##"{"category_id": "QRX3DkDSwjEiq6UQ", "industry_id": "mBwixqBFm3GtJqPC", "order_by": ["title"], "page": 1, "search": "Search"}"##).unwrap();
    client
        .brands()
        .catalog(params)
        .await
        .expect("brands.catalog");

    let requests = server.received_requests().await.unwrap();
    assert_eq!(requests.len(), 1, "brands.catalog");
    let request = &requests[0];
    assert_eq!(request.method.as_str(), "GET");
    assert_eq!(request.url.path(), "/api/v1/brands/catalog/");
    {
        let pairs: Vec<(String, String)> = request
            .url
            .query_pairs()
            .map(|(name, value)| (name.to_string(), value.to_string()))
            .collect();
        let sent = |name: &str| -> Vec<String> {
            pairs
                .iter()
                .filter(|(key, _)| key == name)
                .map(|(_, value)| value.clone())
                .collect()
        };
        assert_eq!(
            sent("category_id"),
            vec!["QRX3DkDSwjEiq6UQ"],
            "brands.catalog sent a wrong ?category_id"
        );
        assert_eq!(
            sent("industry_id"),
            vec!["mBwixqBFm3GtJqPC"],
            "brands.catalog sent a wrong ?industry_id"
        );
        assert_eq!(
            sent("order_by"),
            vec!["title"],
            "brands.catalog sent a wrong ?order_by"
        );
        assert_eq!(sent("page"), vec!["1"], "brands.catalog sent a wrong ?page");
        assert_eq!(
            sent("search"),
            vec!["Search"],
            "brands.catalog sent a wrong ?search"
        );
    }
}

