        serde_json::from_str(r##"{"brand_id": "brd_tp6wqSj7PlBzhPTC", "comment_count": 42, "comment_count_max": 42, "comment_count_min": 42, "content_form": "VIDEO", "creator_follower_count": 42, "creator_follower_count_max": 42, "creator_follower_count_min": 42, "creator_id": "cr_3GNfoiZMbW5eVDkZ", "creator_username": "zelfai", "earned_media_value_cents": 12500000, "earned_media_value_cents_max": 12500000, "earned_media_value_cents_min": 12500000, "engagement_rate": 0.0425, "engagement_rate_max": 0.0425, "engagement_rate_min": 0.0425, "external_id": "ArPpZz8S3TbqrOcb", "is_influencer": true, "is_owned": true, "is_tagged": true, "language": ["en"], "like_count": 42, "like_count_max": 42, "like_count_min": 42, "media_duration": 0.0425, "media_duration_max": 0.0425, "media_duration_min": 0.0425, "mention_type": ["content"], "mention_type_not": ["content"], "net_promoter_score": 7, "net_promoter_score_max": 7, "net_promoter_score_min": 7, "order_by": ["posted_at"], "page": 1, "page_size": 1, "platform": ["instagram"], "posted": "2026-01-01T00:00:00Z", "posted_after": "2026-01-01T00:00:00Z", "posted_before": "2026-01-01T00:00:00Z", "posted_within_days": 42, "posted_within_hours": 42, "search": "Search", "share_count": 42, "share_count_max": 42, "share_count_min": 42, "total_engagement": 18400, "total_engagement_max": 7, "total_engagement_min": 7, "view_count": 327400000, "view_count_max": 42, "view_count_min": 42}"##).unwrap();
    let page = client.content().list(params).await.expect("content.list");
