#[tokio::test]
async fn maps_webhooks_list_deliveries() {
    let server = MockServer::start().await;
    mount(
        &server,
        "GET",
        "/api/v1/webhooks/deliveries/",
        envelope_for("webhooks_list_deliveries"),
    )
    .await;
    let client = client_for(&server);
    let params: WebhooksListDeliveriesParams =
        serde_json::from_str(r##"{"created": "2026-01-01T00:00:00Z", "created_after": "2026-01-01T00:00:00Z", "created_before": "2026-01-01T00:00:00Z", "page": 1, "page_size": 1, "sort_by": ["created"], "state": "PENDING", "state!": "PENDING", "subscription": "Subscription"}"##).unwrap();
    client
        .webhooks()
        .list_deliveries(params)
        .await
        .expect("webhooks.list_deliveries");

    let requests = server.received_requests().await.unwrap();
    assert_eq!(requests.len(), 1, "webhooks.list_deliveries");
    let request = &requests[0];
    assert_eq!(request.method.as_str(), "GET");
    assert_eq!(request.url.path(), "/api/v1/webhooks/deliveries/");
    {
        let pairs: Vec<(String, String)> = request
            .url
            .query_pairs()
            .map(|(name, value)| (name.to_string(), value.to_string()))
            .collect();
        let sent = |name: &str| -> Vec<String> {
            pairs
                .iter()
                .filter(|(key, _)| key == name)
                .map(|(_, value)| value.clone())
                .collect()
        };
        assert_eq!(
            sent("created"),
            vec!["2026-01-01T00:00:00Z"],
            "webhooks.list_deliveries sent a wrong ?created"
        );
        assert_eq!(
            sent("created_after"),
            vec!["2026-01-01T00:00:00Z"],
            "webhooks.list_deliveries sent a wrong ?created_after"
        );
        assert_eq!(
            sent("created_before"),
            vec!["2026-01-01T00:00:00Z"],
            "webhooks.list_deliveries sent a wrong ?created_before"
        );
        assert_eq!(
            sent("page"),
            vec!["1"],
            "webhooks.list_deliveries sent a wrong ?page"
        );
        assert_eq!(
            sent("page_size"),
            vec!["1"],
            "webhooks.list_deliveries sent a wrong ?page_size"
        );
        assert_eq!(
            sent("sort_by"),
            vec!["created"],
            "webhooks.list_deliveries sent a wrong ?sort_by"
        );
        assert_eq!(
            sent("state"),
            vec!["PENDING"],
            "webhooks.list_deliveries sent a wrong ?state"
        );
        assert_eq!(
            sent("state!"),
            vec!["PENDING"],
            "webhooks.list_deliveries sent a wrong ?state!"
        );
        assert_eq!(
            sent("subscription"),
            vec!["Subscription"],
            "webhooks.list_deliveries sent a wrong ?subscription"
        );
    }
}

