#[tokio::test]
async fn maps_webhooks_update_subscription() {
    let server = MockServer::start().await;
    mount(
        &server,
        "PATCH",
        "/api/v1/webhooks/subscriptions/whs_BeCimgZiCdOSa6ee/",
        envelope_for("webhooks_update_subscription"),
    )
    .await;
    let client = client_for(&server);
    let params: WebhooksUpdateSubscriptionParams =
        serde_json::from_str(r##"{"url": "https://example.com/request/url", "resource_filters": {}, "custom_headers": {}, "interval_hours": 12, "max_items": 10, "enabled": true}"##).unwrap();
    client
        .webhooks()
        .update_subscription("whs_BeCimgZiCdOSa6ee", params)
        .await
        .expect("webhooks.update_subscription");

    let requests = server.received_requests().await.unwrap();
    assert_eq!(requests.len(), 1, "webhooks.update_subscription");
    let request = &requests[0];
    assert_eq!(request.method.as_str(), "PATCH");
    assert_eq!(
        request.url.path(),
        "/api/v1/webhooks/subscriptions/whs_BeCimgZiCdOSa6ee/"
    );
    {
        let body: serde_json::Value =
            serde_json::from_slice(&request.body).unwrap_or(serde_json::Value::Null);
        assert!(
            body.get("custom_headers").is_some(),
            "webhooks.update_subscription dropped custom_headers"
        );
        assert!(
            body.get("enabled").is_some(),
            "webhooks.update_subscription dropped enabled"
        );
        assert!(
            body.get("interval_hours").is_some(),
            "webhooks.update_subscription dropped interval_hours"
        );
        assert!(
            body.get("max_items").is_some(),
            "webhooks.update_subscription dropped max_items"
        );
        assert!(
            body.get("resource_filters").is_some(),
            "webhooks.update_subscription dropped resource_filters"
        );
        assert!(
            body.get("url").is_some(),
            "webhooks.update_subscription dropped url"
        );
    }
}

